export const uid=()=>crypto.randomUUID();
export const normalize=s=>String(s||'').trim().replace(/\s+/g,' ').replace(/\s+([.,!?;:])/g,'$1').toLocaleLowerCase();
export function score(q,a){if(q.type==='multi'){let x=Array.isArray(a)?a:[];let y=String(q.answer).split(/[|,]/).map(s=>s.trim().toUpperCase()).sort();return x.map(s=>s.toUpperCase()).sort().join('|')===y.join('|')}if(q.type==='sentence')return [q.answer,...(q.alternatives||[])].some(x=>normalize(x)===normalize(a));return normalize(a)===normalize(q.answer)}
export function parseCSV(text){let rows=[],row=[],field='',quoted=false;for(let i=0;i<text.length;i++){let c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){field+='"';i++}else quoted=!quoted}else if(c===','&&!quoted){row.push(field);field=''}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&text[i+1]==='\n')i++;row.push(field);if(row.some(x=>x.trim()))rows.push(row);row=[];field=''}else field+=c}row.push(field);if(row.some(x=>x.trim()))rows.push(row);if(quoted)throw Error('Dấu ngoặc kép chưa đóng');if(!rows.length)return [];let h=rows.shift().map(x=>x.trim().toLowerCase().replace(/^\ufeff/,''));return rows.map(r=>Object.fromEntries(h.map((x,i)=>[x,r[i]||''])))}
export function rowQuestion(r){let type=(r.type||'single').toLowerCase().trim();type=({multiple_choice:'single',multiple:'multi',true_false:'truefalse',fill:'blank'})[type]||type;let q={id:uid(),type,prompt:r.question||r.prompt||'',options:[r.option_a||'',r.option_b||'',r.option_c||'',r.option_d||''],answer:r.correct_answer||r.answer||'',explanation:r.explanation||'',topic:r.topic||'',difficulty:r.difficulty||'Trung bình'};if(type==='truefalse'&&!q.options.some(Boolean))q.options=['True','False'];return q}
export function validate(q){let e=[];if(!['single','multi','truefalse','blank','sentence'].includes(q.type))e.push('Loại không hợp lệ');if(!q.prompt.trim())e.push('Thiếu câu hỏi');if(!q.answer.trim())e.push('Thiếu đáp án');if(['single','multi','truefalse'].includes(q.type)){let answers=q.answer.toUpperCase().split(/[|,]/).map(x=>x.trim());if(answers.some(x=>!['A','B','C','D'].includes(x)||!q.options[x.charCodeAt(0)-65]))e.push('Đáp án phải là chữ cái của lựa chọn có nội dung')}return e}
export function parseText(text){return text.trim().split(/\n\s*\n/).filter(Boolean).map(block=>{let r={};for(let line of block.split(/\r?\n/)){let m=line.match(/^\s*(TYPE|Q|QUESTION|PROMPT|ANSWER|EXPLANATION|TOPIC|DIFFICULTY)\s*:\s*(.*)$/i)||line.match(/^\s*([A-D])\.\s*(.*)$/i);if(m){let k=m[1].toLowerCase();r[({q:'question',a:'option_a',b:'option_b',c:'option_c',d:'option_d'})[k]||k]=m[2]}}return rowQuestion(r)})}
export function dayKey(date=new Date()){return new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Ho_Chi_Minh',year:'numeric',month:'2-digit',day:'2-digit'}).format(date)}
export function stats(attempts){let correct=attempts.filter(a=>a.correct).length;return {total:attempts.length,correct,accuracy:attempts.length?Math.round(correct/attempts.length*100):0,unique:new Set(attempts.map(a=>a.questionId)).size,seconds:attempts.reduce((s,a)=>s+(a.seconds||0),0)}}
export function csvEscape(x){let s=String(x??'');return /[",\n\r]/.test(s)?'"'+s.replaceAll('"','""')+'"':s}
export function toCSV(qs){let h=['type','question','option_a','option_b','option_c','option_d','correct_answer','explanation','topic','difficulty'];return [h.join(','),...qs.map(q=>[q.type,q.prompt,...q.options,q.answer,q.explanation,q.topic,q.difficulty].map(csvEscape).join(','))].join('\r\n')}
